#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Ticket 01: Supabase project, Telegram bot and GitHub secrets. Re-run any
# time to rotate a value: stages with saved values ask before changing them.

cd "$(git rev-parse --show-toplevel)"

TOTAL_STAGES=5

# keep_existing KEY...: true when every KEY already has a value in .env and
# the human doesn't want to change it.
keep_existing() {
  local k
  for k in "$@"; do _existing "$k" >/dev/null || return 1; done
  note "Already saved: $*"
  ! confirm "Change (rotate) it?"
}

# json_get FIELD.PATH reads one value from JSON on stdin; empty on failure.
json_get() {
  python3 -c '
import json, sys
try:
    v = json.load(sys.stdin)
    for p in sys.argv[1].split("."):
        v = v[int(p)] if isinstance(v, list) else v[p]
    print(v)
except Exception:
    pass
' "$1"
}

banner "Tennis notifier: Supabase, Telegram bot and GitHub secrets"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight: GitHub CLI and a git-ignored .env"
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  note "gh is signed in; secrets go to $(gh repo view --json nameWithOwner -q .nameWithOwner)."
else
  warn "gh isn't installed or signed in, so GitHub secrets will be skipped."
  say "Fix it in another terminal with: gh auth login (then re-run this wizard)."
  confirm "Carry on anyway (values still go to .env)?" || exit 1
fi
if git check-ignore -q "$ENV_FILE"; then
  note "$ENV_FILE is git-ignored. Good, the repo is public."
else
  warn "$ENV_FILE isn't git-ignored, and this repo is public."
  if confirm "Add $ENV_FILE to .gitignore now?"; then
    printf '%s\n' "$ENV_FILE" >> .gitignore
    printf '  %s✓ added%s %s to .gitignore (commit that change)\n' "$GREEN" "$RESET" "$ENV_FILE"
  else
    say "Not writing secrets to an un-ignored file. Stopping."; exit 1
  fi
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Telegram: create the bot"
if keep_existing TELEGRAM_BOT_TOKEN TELEGRAM_BOT_USERNAME; then
  TELEGRAM_BOT_TOKEN=$(_existing TELEGRAM_BOT_TOKEN)
  TELEGRAM_BOT_USERNAME=$(_existing TELEGRAM_BOT_USERNAME)
else
  say "BotFather creates the bot and gives you its token."
  open_url "https://t.me/BotFather"
  step "In Telegram, send /newbot to @BotFather (to rotate: /revoke, then pick the bot)."
  step "Give it a display name, then a username ending in 'bot'."
  step "Copy the token it replies with (looks like 123456789:AA...)."
  while :; do
    ask_secret TELEGRAM_BOT_TOKEN "Paste the bot token:"
    me=$(curl -fsS "https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/getMe" 2>/dev/null || true)
    TELEGRAM_BOT_USERNAME=$(printf '%s' "$me" | json_get result.username)
    [[ -n "$TELEGRAM_BOT_USERNAME" ]] && break
    warn "Telegram didn't accept that token. Try pasting it again."
  done
  note "Token works: this is @$TELEGRAM_BOT_USERNAME."
  write_env TELEGRAM_BOT_TOKEN "$TELEGRAM_BOT_TOKEN"
  write_env TELEGRAM_BOT_USERNAME "$TELEGRAM_BOT_USERNAME"
  set_secret TELEGRAM_BOT_TOKEN "$TELEGRAM_BOT_TOKEN"
fi
note "Leave /setdomain for now; it waits for GitHub Pages (ticket 14)."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Telegram: your owner id"
if ! keep_existing OWNER_TELEGRAM_ID; then
  say "Your numeric Telegram id seeds the owner row later. It also proves the bot can DM you."
  open_url "https://t.me/$TELEGRAM_BOT_USERNAME"
  step "Open the chat with @$TELEGRAM_BOT_USERNAME and press Start (or send it any message)."
  pause "Press Enter once you've sent it a message."
  updates=$(curl -fsS "https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/getUpdates" 2>/dev/null || true)
  found_id=$(printf '%s' "$updates" | python3 -c '
import json, sys
try:
    ids = [u["message"]["from"]["id"] for u in json.load(sys.stdin)["result"] if "message" in u]
    print(ids[-1] if ids else "")
except Exception:
    pass
')
  if [[ -n "$found_id" ]]; then
    note "The bot saw a message from id $found_id."
    OWNER_TELEGRAM_ID=$found_id
    confirm "Is that you?" || ask OWNER_TELEGRAM_ID "Type your Telegram id:"
  else
    warn "The bot hasn't seen your message yet."
    note "Another way: message @userinfobot in Telegram; it replies with your id."
    ask OWNER_TELEGRAM_ID "Type your Telegram id:"
  fi
  until [[ "$OWNER_TELEGRAM_ID" =~ ^[0-9]+$ ]]; do
    warn "A Telegram id is digits only."
    ask OWNER_TELEGRAM_ID "Type your Telegram id:"
  done
  write_env OWNER_TELEGRAM_ID "$OWNER_TELEGRAM_ID"   # .env only: member data never goes to GitHub
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Supabase: create the project"
if keep_existing SUPABASE_URL; then
  SUPABASE_URL=$(_existing SUPABASE_URL)
else
  say "One free Supabase project holds all the notifier's data."
  open_url "https://supabase.com/dashboard/projects"
  step "Sign in (GitHub login is fine). New account? First 'New organization': Personal, Free plan."
  step "Then 'New project'. Name: tennis-notifier. Region: West Europe (London), close to Camden."
  step "Database password: generate one, Copy it, save it in your password manager."
  step "Security: keep 'Enable Data API', UNtick 'Automatically expose new tables',"
  step "tick 'Enable automatic RLS'. Leave GitHub and Advanced configuration alone."
  step "Create it. The URL is https://<ref>.supabase.co, where <ref> is the id in the"
  step "dashboard address (supabase.com/dashboard/project/<ref>), or copy it from 'Connect'."
  ask SUPABASE_URL "Paste the Project URL:"
  SUPABASE_URL=${SUPABASE_URL%/}
  until [[ "$SUPABASE_URL" =~ ^https://[a-z0-9]+\.supabase\.co$ ]]; do
    warn "Expected something like https://abcdefghijklmnop.supabase.co"
    ask SUPABASE_URL "Paste the Project URL:"
    SUPABASE_URL=${SUPABASE_URL%/}
  done
  write_env SUPABASE_URL "$SUPABASE_URL"
  set_secret SUPABASE_URL "$SUPABASE_URL"
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Supabase: the service key"
if ! keep_existing SUPABASE_SERVICE_KEY; then
  say "The poller uses this key to call the database functions. It bypasses RLS, so keep it secret."
  ref=${SUPABASE_URL#https://}; ref=${ref%%.*}
  open_url "https://supabase.com/dashboard/project/$ref/settings/api-keys"
  step "Go to Project Settings → API Keys."
  step "Copy a secret key (starts sb_secret_; click to reveal). To rotate, create a new one there"
  step "and delete the old one after this wizard finishes."
  step "Older projects may only show the legacy 'service_role' key (a long eyJ... token). That works too."
  while :; do
    ask_secret SUPABASE_SERVICE_KEY "Paste the secret key:"
    if [[ "$SUPABASE_SERVICE_KEY" == sb_secret_* ]]; then
      code=$(curl -s -o /dev/null -w '%{http_code}' "$SUPABASE_URL/rest/v1/" -H "apikey: $SUPABASE_SERVICE_KEY" || true)
    else
      code=$(curl -s -o /dev/null -w '%{http_code}' "$SUPABASE_URL/rest/v1/" \
        -H "apikey: $SUPABASE_SERVICE_KEY" -H "Authorization: Bearer $SUPABASE_SERVICE_KEY" || true)
    fi
    [[ "$code" == 200 ]] && { note "Supabase accepted the key."; break; }
    warn "Supabase answered HTTP $code with that key."
    confirm "Save it anyway?" && break
  done
  write_env SUPABASE_SERVICE_KEY "$SUPABASE_SERVICE_KEY"
  set_secret SUPABASE_SERVICE_KEY "$SUPABASE_SERVICE_KEY"
fi
pause

finish
note "Next: ticket 02 can now run live against $SUPABASE_URL."
note "Check the secrets any time with: gh secret list"
